import {readdir,readFile,realpath,stat,writeFile,mkdir} from 'node:fs/promises';
import {join,basename,relative} from 'node:path';
import {homedir} from 'node:os';
import {zipSync,strToU8} from 'fflate';
const id='desartly-skill-bundle',entries={},manifest=[],excluded=[],seen=new Set(),names=new Set();
const codexRoot=process.env.CODEX_HOME||join(homedir(),'.codex'),roots=[join(codexRoot,'skills'),join(homedir(),'.agents/skills'),join(codexRoot,'plugins/cache/openai-bundled'),join(codexRoot,'plugins/cache/openai-curated-remote'),join(codexRoot,'plugins/cache/openai-primary-runtime')];
const skipped=new Set(['node_modules','.git','__pycache__','.venv','venv','.cache']);
async function discover(dir){let items;try{items=await readdir(dir,{withFileTypes:true});}catch{return;}if(items.some(i=>i.name==='SKILL.md'))return add(dir);for(const item of items){if(skipped.has(item.name)||item.name.startsWith('.')&&item.name!=='.system')continue;if(item.isDirectory()||item.isSymbolicLink())await discover(join(dir,item.name));}}
async function add(dir){const canonical=await realpath(dir);if(seen.has(canonical))return;seen.add(canonical);const skill=await readFile(join(dir,'SKILL.md'),'utf8'),name=skill.match(/^name:\s*(.+)$/m)?.[1]?.trim().replace(/^['"]|['"]$/g,'')||basename(dir);let slug=basename(dir).replace(/[^a-zA-Z0-9_-]/g,'-');if(names.has(slug)){let n=2;while(names.has(slug+'-'+n))n++;slug+='-'+n;}names.add(slug);let files=0,bytes=0;async function walk(path){for(const item of await readdir(path,{withFileTypes:true})){if(skipped.has(item.name)||item.name.startsWith('.')||/^(session|credentials|token|secrets?)(\.|$)/i.test(item.name)||/\.(pem|key|p12)$/i.test(item.name))continue;const file=join(path,item.name),rel=relative(dir,file);if(item.isDirectory())await walk(file);else if(item.isFile()){const data=await readFile(file);if(data.length>20000000){excluded.push({skill:name,file:rel,reason:'File exceeds bundle size limit'});continue;}if(data.length<2000000&&!data.includes(0)&&/(?:ghp_[A-Za-z0-9]{30,}|sk-proj-[A-Za-z0-9_-]{40,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----)/.test(data.toString('utf8'))){excluded.push({skill:name,file:rel,reason:'Credential-like content'});continue;}entries[id+'/library/'+slug+'/'+rel]=data;files++;bytes+=data.length;}}}await walk(dir);manifest.push({name,folder:slug,description:skill.match(/^description:\s*(.+)$/m)?.[1]?.trim()||'',files,bytes});}
for(const root of roots)await discover(root);
entries[id+'/SKILL.md']=strToU8('---\nname: '+id+'\ndescription: Browse Ali’s installed skill collection and select the smallest relevant skill for a task.\nmetadata:\n  version: "1.0.0"\n---\n\n# Personal skill collection\n\nRead `manifest.json` to locate relevant skills. Read only the selected library/<folder>/SKILL.md and its needed references; do not load the entire bundle into context. The library preserves source instructions, licenses, scripts and assets. Do not install every skill automatically. Choose the requested skills and copy their individual folders into your agent’s supported skill directory. External tool dependencies and plugin connections still require their original environment. This bundle contains no CMS login or access token.\n');
entries[id+'/manifest.json']=strToU8(JSON.stringify({version:'1.0.0',skills:manifest,excluded},null,2));
const archive=zipSync(entries,{level:6});console.log(JSON.stringify({bytes:archive.length,skills:manifest.length,largest:manifest.sort((a,b)=>b.bytes-a.bytes).slice(0,8).map(s=>({name:s.name,bytes:s.bytes}))}));if(archive.length>64000000)throw Error('Bundle exceeds upload limit');await mkdir('private-artifacts',{recursive:true});await writeFile('private-artifacts/desartly-skill-bundle.zip',archive);await writeFile('private-artifacts/skill-manifest.json',JSON.stringify({count:manifest.length,files:Object.keys(entries).length,bytes:archive.length,expandedBytes:manifest.reduce((a,s)=>a+s.bytes,0),excluded},null,2));console.log(JSON.stringify({skills:manifest.length,files:Object.keys(entries).length,bytes:archive.length,excluded:excluded.length}));
